function ndb_e(string $v): string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}function ndb_flash(string $type,string $msg): void{$_SESSION['ndb_flash']=[$type,$msg];}function ndb_take_flash(): ?array{$x=$_SESSION['ndb_flash']??null;unset($_SESSION['ndb_flash']);return is_array($x)?$x:null;}function ndb_job_read(): array{if(!is_file(NDB_JOB_FILE))return[];$j=json_decode((string)@file_get_contents(NDB_JOB_FILE),true);return is_array($j)?$j:[];}function ndb_job_running(array $job): bool{$pid=(int)($job['pid']??0);if($pid<=0||!is_dir('/proc/'.$pid))return false;$cmd=@file_get_contents('/proc/'.$pid.'/cmdline');return $cmd===false||str_contains(str_replace("\0",' ',$cmd),'augur-depa-backfill-cli.php');}function ndb_tail(string $path,int $n=80): string{if(!is_file($path))return'';$x=@file($path,FILE_IGNORE_NEW_LINES);return is_array($x)?implode("\n",array_slice($x,-$n)):'';}function ndb_exec_available(): bool{$disabled=array_map('trim',explode(',',(string)ini_get('disable_functions')));return function_exists('exec')&&!in_array('exec',$disabled,true);}
function ndb_launch(int $start,int $end): array{if(!ndb_exec_available())throw new RuntimeException('PHP exec() is disabled; run the CLI command shown below instead.');$existing=ndb_job_read();if($existing&&ndb_job_running($existing))throw new RuntimeException('A D-EPA rebuild is already running.');$php=is_executable('/usr/bin/php')?'/usr/bin/php':PHP_BINARY;$script=__DIR__.'/augur-depa-backfill-cli.php';if(!is_file($script))throw new RuntimeException('D-EPA CLI script is missing.');if(!is_dir(NDB_JOB_DIR)&&!mkdir(NDB_JOB_DIR,0770,true)&&!is_dir(NDB_JOB_DIR))throw new RuntimeException('Could not create D-EPA job directory.');$log=NDB_JOB_DIR.'/depa-'.date('Ymd-His').'.log';$cmd='nohup '.escapeshellarg($php).' '.escapeshellarg($script).' '.escapeshellarg((string)$start).' '.escapeshellarg((string)$end).' >> '.escapeshellarg($log).' 2>&1 < /dev/null & echo $!';$o=[];$code=0;exec($cmd,$o,$code);$pid=(int)trim((string)($o[0]??'0'));if($code!==0||$pid<=0)throw new RuntimeException('Could not start the D-EPA background rebuild.');$job=['pid'=>$pid,'start_year'=>$start,'end_year'=>$end,'log'=>$log,'started_at'=>date(DATE_ATOM)];file_put_contents(NDB_JOB_FILE,json_encode($job,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),LOCK_EX);return $job;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$op=(string)($_POST['op']??'');try{if($op==='install'){augur_depa_install_tables($pdo);ndb_flash('good','Neptune D-EPA network tables are installed.');}elseif($op==='rebuild'){$start=(int)($_POST['start_year']??date('Y'));$end=(int)($_POST['end_year']??$start);$max=(int)date('Y')+1;if($start<1992||$end<1992||$start>$max||$end>$max)throw new RuntimeException('Choose a valid FRC season range.');if($start>$end)[$start,$end]=[$end,$start];augur_depa_install_tables($pdo);ndb_launch($start,$end);ndb_flash('good',"Neptune-wide D-EPA rebuild started for {$start}–{$end}.");}}catch(Throwable $e){ndb_flash('bad',$e->getMessage());}header('Location: '.base_url('admin/augur-depa-beta.php'));exit;}
$ready=augur_depa_tables_ready($pdo);
$schemaCurrent=false;
try{
    $q=$pdo->prepare("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='augur_depa_public_season_ratings' AND COLUMN_NAME IN ('public_depa','public_matches','defense_failures','defense_attempts')");
    $q->execute();
    $schemaCurrent=((int)$q->fetchColumn()===4);
}catch(Throwable $e){}
$job=ndb_job_read();$running=$job&&ndb_job_running($job);$log=$job?ndb_tail((string)($job['log']??'')):'';$flash=ndb_take_flash();$current=(int)date('Y');
$stats=['samples'=>0,'network'=>0,'event'=>0,'season'=>0,'orgs'=>0,'latest'=>null];if($ready){try{$stats['samples']=(int)$pdo->query('SELECT COUNT(*) FROM augur_depa_match_samples')->fetchColumn();}catch(Throwable $e){}try{$stats['network']=(int)$pdo->query('SELECT COUNT(*) FROM augur_depa_network_match_evidence')->fetchColumn();}catch(Throwable $e){}try{$stats['event']=(int)$pdo->query('SELECT COUNT(*) FROM augur_depa_public_event_ratings WHERE observed_matches>0')->fetchColumn();}catch(Throwable $e){}try{$stats['season']=(int)$pdo->query('SELECT COUNT(*) FROM augur_depa_public_season_ratings')->fetchColumn();}catch(Throwable $e){}try{$stats['orgs']=(int)$pdo->query("SELECT COUNT(DISTINCT sa.organization_id) FROM scouting_actions sa JOIN events e ON e.id=sa.event_id WHERE sa.deleted_at IS NULL AND e.tba_event_key IS NOT NULL AND e.tba_event_key<>''")->fetchColumn();}catch(Throwable $e){}try{$stats['latest']=$pdo->query('SELECT MAX(calculated_at) FROM augur_depa_public_season_ratings')->fetchColumn()?:null;}catch(Throwable $e){}}
